#define UNICODE
#define _UNICODE
#include <windows.h>
#include <stdio.h>
#include <wchar.h>

typedef struct {
    DWORD pid;
    HWND dialog;
    WCHAR title[128];
    WCHAR message[128];
} Observation;

static BOOL CALLBACK observe_control(HWND control, LPARAM arg) {
    Observation *observation = (Observation *)arg;
    WCHAR class_name[32], text[128] = {0};
    DWORD_PTR length = 0;
    if (!GetClassNameW(control, class_name, ARRAYSIZE(class_name)) || wcscmp(class_name, L"Static")) {
        return TRUE;
    }
    if (SendMessageTimeoutW(control, WM_GETTEXT, ARRAYSIZE(text), (LPARAM)text,
                            SMTO_BLOCK | SMTO_ABORTIFHUNG, 300, &length) && length) {
        if (wcscmp(text, L"Hello, World!") == 0) {
            wcscpy(observation->message, text);
            return FALSE;
        }
    }
    return TRUE;
}

static BOOL CALLBACK observe_window(HWND window, LPARAM arg) {
    Observation *observation = (Observation *)arg;
    DWORD owner;
    WCHAR class_name[64], title[128];
    GetWindowThreadProcessId(window, &owner);
    if (owner != observation->pid || !GetClassNameW(window, class_name, ARRAYSIZE(class_name)) ||
        wcscmp(class_name, L"#32770") || !GetWindowTextW(window, title, ARRAYSIZE(title))) {
        return TRUE;
    }
    if (wcscmp(title, L"Corpus greeting") != 0) {
        fwprintf(stderr, L"Unexpected child dialog: %ls\n", title);
        return TRUE;
    }
    EnumChildWindows(window, observe_control, arg);
    if (!observation->message[0]) {
        return TRUE;
    }
    observation->dialog = window;
    wcscpy(observation->title, title);
    return FALSE;
}

int main(void) {
    STARTUPINFOW startup = {0};
    PROCESS_INFORMATION process = {0};
    DWORD exit_code = 1;
    int result = 1;
    startup.cb = sizeof(startup);
    if (!CreateProcessW(L".\\corpus_hello.exe", NULL, NULL, NULL, FALSE, 0, NULL, NULL,
                        &startup, &process)) {
        fwprintf(stderr, L"CreateProcessW failed: %lu\n", GetLastError());
        return 1;
    }
    CloseHandle(process.hThread);
    Observation observation = { .pid = process.dwProcessId };
    const ULONGLONG deadline = GetTickCount64() + 15000;
    while (GetTickCount64() < deadline && WaitForSingleObject(process.hProcess, 0) == WAIT_TIMEOUT) {
        EnumWindows(observe_window, (LPARAM)&observation);
        if (observation.dialog) {
            HWND button = GetDlgItem(observation.dialog, IDOK);
            wprintf(L"title=%ls\nmessage=%ls\n", observation.title, observation.message);
            fflush(stdout);
            if (button && PostMessageW(button, BM_CLICK, 0, 0) &&
                WaitForSingleObject(process.hProcess, 10000) == WAIT_OBJECT_0 &&
                GetExitCodeProcess(process.hProcess, &exit_code)) {
                wprintf(L"child_exit_code=%lu\n", exit_code);
                result = exit_code == 0 ? 0 : 1;
            }
            break;
        }
        Sleep(150);
    }
    if (result != 0) {
        fwprintf(stderr, L"The greeting dialog or clean child exit was not observed.\n");
        if (WaitForSingleObject(process.hProcess, 0) == WAIT_TIMEOUT) {
            TerminateProcess(process.hProcess, 2);
        }
    }
    CloseHandle(process.hProcess);
    return result;
}

import_driver_source:
#include <windows.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int level;
    const char *number;
    const char *text;
    unsigned int column;
    unsigned int line;
} CompileError;

typedef void (CALLBACK *ErrorCallback)(const CompileError *, void *);
typedef HANDLE (WINAPI *SessionOpen)(void);
typedef void (WINAPI *SessionClose)(HANDLE);
typedef void (WINAPI *SessionGetError)(HANDLE, char *, int);
typedef int (WINAPI *LibraryCreate)(HANDLE, const char *, const char *);
typedef int (WINAPI *SetLibraryList)(HANDLE, const char **, int);
typedef int (WINAPI *SetApplication)(HANDLE, const char *, const char *);
typedef int (WINAPI *CompileImport)(HANDLE, const char *, const char *, int, const char *,
                                    const char *, long, ErrorCallback, void *);
typedef int (WINAPI *ApplicationRebuild)(HANDLE, int, ErrorCallback, void *);
typedef void (CALLBACK *LinkCallback)(const void *, void *);
typedef int (WINAPI *ExecutableCreate)(HANDLE, const char *, const char *, const char *,
                                       LinkCallback, void *, int *, int, long, void *);

enum { APPLICATION = 0, USER_OBJECT = 6 };

static void CALLBACK report_error(const CompileError *error, void *unused) {
    (void)unused;
    fprintf(stderr, "%u:%u level=%d %s %s\n", error->line, error->column, error->level,
            error->number ? error->number : "", error->text ? error->text : "");
}

static int import_file(CompileImport compile, HANDLE session, const char *library,
                       const char *filename, const char *name, int type) {
    char buffer[4097];
    FILE *source = fopen(filename, "rb");
    if (!source) {
        perror(filename);
        return 1;
    }
    size_t length = fread(buffer, 1, sizeof(buffer) - 1, source);
    int invalid = ferror(source) || !feof(source) || length == 0;
    fclose(source);
    if (invalid) {
        fprintf(stderr, "Could not read bounded source: %s\n", filename);
        return 1;
    }
    buffer[length] = '\0';
    int result = compile(session, library, name, type, "Local corpus verification",
                         buffer, (long)length, report_error, NULL);
    printf("PBORCA_CompileEntryImport %s bytes=%zu status=%d\n", filename, length, result);
    return result;
}

int main(void) {
    setvbuf(stdout, NULL, _IONBF, 0);
    char library[MAX_PATH], application_exe[MAX_PATH], icon[MAX_PATH];
    DWORD length = GetFullPathNameA("corpus_hello.pbl", ARRAYSIZE(library), library, NULL);
    if (!length || length >= ARRAYSIZE(library)) {
        fputs("Could not resolve the local library path.\n", stderr);
        return 1;
    }
    length = GetFullPathNameA("corpus_hello.exe", ARRAYSIZE(application_exe), application_exe, NULL);
    if (!length || length >= ARRAYSIZE(application_exe)) {
        fputs("Could not resolve the local executable path.\n", stderr);
        return 1;
    }
    length = GetFullPathNameA("PowerBuilderCompiler.ico", ARRAYSIZE(icon), icon, NULL);
    if (!length || length >= ARRAYSIZE(icon) || GetFileAttributesA(icon) == INVALID_FILE_ATTRIBUTES) {
        fputs("Could not resolve the staged compiler icon.\n", stderr);
        return 1;
    }
    HMODULE orca = LoadLibraryW(L"pborc.dll");
    if (!orca) {
        fprintf(stderr, "LoadLibraryW(pborc.dll) failed: %lu\n", GetLastError());
        return 1;
    }

    SessionOpen open = (SessionOpen)GetProcAddress(orca, "PBORCA_SessionOpenA");
    SessionClose close = (SessionClose)GetProcAddress(orca, "PBORCA_SessionClose");
    SessionGetError get_error = (SessionGetError)GetProcAddress(orca, "PBORCA_SessionGetError");
    LibraryCreate create = (LibraryCreate)GetProcAddress(orca, "PBORCA_LibraryCreate");
    SetLibraryList set_libraries = (SetLibraryList)GetProcAddress(orca, "PBORCA_SessionSetLibraryList");
    SetApplication set_application = (SetApplication)GetProcAddress(orca, "PBORCA_SessionSetCurrentAppl");
    CompileImport compile = (CompileImport)GetProcAddress(orca, "PBORCA_CompileEntryImport");
    ApplicationRebuild rebuild = (ApplicationRebuild)GetProcAddress(orca, "PBORCA_ApplicationRebuild");
    ExecutableCreate executable = (ExecutableCreate)GetProcAddress(orca, "PBORCA_ExecutableCreate");
    if (!open || !close || !get_error || !create || !set_libraries || !set_application || !compile ||
        !rebuild || !executable) {
        fputs("The required native ORCA exports are missing.\n", stderr);
        return 1;
    }

    HANDLE session = open();
    if (!session) {
        fputs("PBORCA_SessionOpenA did not open a session.\n", stderr);
        return 1;
    }
    const char *libraries[] = {library};
    int result = create(session, library, "Corpus verification staging");
    printf("PBORCA_LibraryCreate status=%d\n", result);
    if (result == 0) {
        result = set_libraries(session, libraries, ARRAYSIZE(libraries));
        printf("PBORCA_SessionSetLibraryList status=%d\n", result);
    }
    if (result == 0) {
        result = set_application(session, NULL, NULL);
        printf("PBORCA bootstrap application status=%d\n", result);
    }
    if (result == 0) {
        result = import_file(compile, session, library, "u_hello.sru", "u_hello", USER_OBJECT);
    }
    if (result == 0) {
        result = import_file(compile, session, library, "corpus_hello.sra", "corpus_hello", APPLICATION);
    }
    close(session);
    if (result != 0) {
        FreeLibrary(orca);
        return 1;
    }

    session = open();
    if (!session) {
        fputs("PBORCA_SessionOpenA did not reopen the application library.\n", stderr);
        FreeLibrary(orca);
        return 1;
    }
    result = set_libraries(session, libraries, ARRAYSIZE(libraries));
    if (result == 0) {
        result = set_application(session, library, "corpus_hello");
    }
    printf("PBORCA select imported application status=%d\n", result);
    if (result == 0) {
        result = rebuild(session, 0, report_error, NULL);
        printf("PBORCA_ApplicationRebuild status=%d\n", result);
    }
    if (result == 0) {
        int include_library_in_executable[] = {0};
        result = executable(session, application_exe, icon, NULL, NULL, NULL,
                            include_library_in_executable, ARRAYSIZE(include_library_in_executable), 0, NULL);
        printf("PBORCA_ExecutableCreate status=%d\n", result);
        if (result != 0) {
            char error[1024] = {0};
            get_error(session, error, sizeof(error));
            fprintf(stderr, "ORCA executable generation: %s\n", error);
        }
    }
    close(session);
    FreeLibrary(orca);
    return result == 0 ? 0 : 1;
}
